  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">

  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --bg: #0A0A0A;
      --bg-elevated: #141414;
      --bg-card: #1A1A1A;
      --bg-card-hover: #222222;
      --text-primary: #FFFFFF;
      --text-secondary: #A0A0A0;
      --text-muted: #666666;
      --accent: #3B82F6;
      --accent-hover: #60A5FA;
      --accent-warm: #F59E0B;
      --border: #2A2A2A;
      --border-light: #333333;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --max-width: 1400px;
      --section-padding: clamp(80px, 10vw, 140px);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
    img { max-width: 100%; display: block; }
    ul, ol { list-style: none; }

    .container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 clamp(20px, 4vw, 60px);
    }

    /* ===== HEADER / NAV ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(10, 10, 10, 0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid rgba(255,255,255,0.06);
      transition: background 0.3s;
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 clamp(20px, 4vw, 60px);
    }

    .logo {
      font-size: 1.35rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      white-space: nowrap;
    }

    .logo span { color: var(--accent); }

    .nav-desktop { display: flex; align-items: center; gap: 32px; }

    .nav-desktop a {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color 0.2s;
      white-space: nowrap;
    }

    .nav-desktop a:hover { color: var(--text-primary); }

    .nav-right { display: flex; align-items: center; gap: 20px; }

    .lang-selector {
      position: relative;
      font-size: 0.8rem;
      font-weight: 500;
      color: var(--text-secondary);
    }

    .lang-selector-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.8rem;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color 0.2s;
      padding: 6px 10px;
      border-radius: 6px;
    }

    .lang-selector-btn:hover { color: var(--text-primary); }

    .lang-selector-btn svg {
      width: 12px;
      height: 12px;
      transition: transform 0.2s;
    }

    .lang-selector.open .lang-selector-btn svg { transform: rotate(180deg); }

    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 6px;
      min-width: 160px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-6px);
      transition: all 0.2s;
      box-shadow: 0 16px 48px rgba(0,0,0,0.5);
    }

    .lang-selector.open .lang-dropdown {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

    .lang-dropdown button {
      display: block;
      width: 100%;
      text-align: left;
      padding: 10px 14px;
      font-size: 0.85rem;
      border-radius: 6px;
      transition: background 0.15s;
      color: var(--text-secondary);
    }

    .lang-dropdown button:hover { background: var(--bg-elevated); color: var(--text-primary); }
    .lang-dropdown button.active { color: var(--accent); }

    .nav-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 10px 22px;
      background: var(--accent);
      color: #fff;
      font-size: 0.85rem;
      font-weight: 600;
      border-radius: 100px;
      transition: background 0.2s, transform 0.15s;
    }

    .nav-cta:hover { background: var(--accent-hover); transform: translateY(-1px); }

    /* Mobile Nav */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      width: 28px;
      padding: 4px 0;
    }

    .hamburger span {
      display: block;
      height: 2px;
      background: var(--text-primary);
      border-radius: 2px;
      transition: all 0.3s;
    }

    .mobile-nav {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--bg);
      z-index: 999;
      padding: 40px clamp(20px, 4vw, 60px);
      flex-direction: column;
      gap: 24px;
      overflow-y: auto;
    }

    .mobile-nav.open { display: flex; }

    .mobile-nav a {
      font-size: 1.5rem;
      font-weight: 600;
      color: var(--text-secondary);
      transition: color 0.2s;
    }

    .mobile-nav a:hover { color: var(--text-primary); }

    @media (max-width: 900px) {
      .nav-desktop, .nav-cta-wrapper { display: none; }
      .hamburger { display: flex; }
    }

    /* ===== HERO CAROUSEL ===== */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: flex-end;
      padding-top: 72px;
      overflow: hidden;
    }

    .hero-slides {
      position: absolute;
      inset: 0;
      z-index: 0;
    }

    .hero-slide {
      position: absolute;
      inset: 0;
      opacity: 0;
      transition: opacity 0.8s ease;
    }

    .hero-slide.active { opacity: 1; }

    .hero-slide-bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
      filter: brightness(0.35);
    }

    .hero-slide-bg::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, var(--bg) 0%, transparent 50%);
    }

    .hero-content {
      position: relative;
      z-index: 2;
      width: 100%;
      padding-bottom: clamp(60px, 8vw, 120px);
    }

    .hero-card {
      display: none;
      max-width: 680px;
    }

    .hero-card.active { display: block; }

    .hero-label {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 20px;
    }

    .hero-title {
      font-size: clamp(2.2rem, 5vw, 3.8rem);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      margin-bottom: 20px;
    }

    .hero-desc {
      font-size: clamp(1rem, 1.5vw, 1.2rem);
      color: var(--text-secondary);
      line-height: 1.6;
      max-width: 520px;
      margin-bottom: 32px;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 14px 32px;
      background: var(--text-primary);
      color: var(--bg);
      font-size: 0.95rem;
      font-weight: 600;
      border-radius: 100px;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .hero-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(255,255,255,0.15);
    }

    .hero-cta svg { width: 16px; height: 16px; }

    .hero-indicators {
      display: flex;
      gap: 10px;
      margin-top: 48px;
    }

    .hero-dot {
      width: 40px;
      height: 3px;
      background: rgba(255,255,255,0.2);
      border-radius: 3px;
      cursor: pointer;
      transition: background 0.3s;
      overflow: hidden;
      position: relative;
    }

    .hero-dot.active { background: rgba(255,255,255,0.3); }

    .hero-dot.active::after {
      content: '';
      position: absolute;
      left: 0;
      top: 0;
      height: 100%;
      width: 0%;
      background: var(--text-primary);
      border-radius: 3px;
      animation: hero-progress 6s linear forwards;
    }

    @keyframes hero-progress {
      to { width: 100%; }
    }

    /* ===== SECTION SHARED ===== */
    .section-eyebrow {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(2rem, 4vw, 3.2rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      margin-bottom: 16px;
    }

    .section-subtitle {
      font-size: clamp(1rem, 1.5vw, 1.15rem);
      color: var(--text-secondary);
      max-width: 600px;
      line-height: 1.6;
    }

    /* ===== TEAM / GLOBAL STUDIOS ===== */
    .team-section {
      padding: var(--section-padding) 0;
      background: var(--bg);
      overflow: hidden;
    }

    .team-header {
      margin-bottom: 48px;
    }

    .region-tabs {
      display: flex;
      gap: 8px;
      margin-top: 32px;
      flex-wrap: wrap;
    }

    .region-tab {
      padding: 10px 22px;
      font-size: 0.875rem;
      font-weight: 500;
      border-radius: 100px;
      border: 1px solid var(--border);
      color: var(--text-secondary);
      transition: all 0.25s;
      white-space: nowrap;
    }

    .region-tab:hover { border-color: var(--text-muted); color: var(--text-primary); }

    .region-tab.active {
      background: var(--text-primary);
      color: var(--bg);
      border-color: var(--text-primary);
    }

    .team-carousel-wrapper {
      position: relative;
    }

    .team-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding: 10px 0 30px;
      scrollbar-width: none;
    }

    .team-carousel::-webkit-scrollbar { display: none; }

    .team-regions { position: relative; }

    .team-region {
      display: none;
    }

    .team-region.active { display: block; }

    .team-card {
      flex: 0 0 clamp(300px, 35vw, 420px);
      scroll-snap-align: start;
      background: var(--bg-card);
      border-radius: 16px;
      overflow: hidden;
      border: 1px solid var(--border);
      transition: border-color 0.3s, transform 0.3s;
    }

    .team-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
    }

    .team-card-img {
      width: 100%;
      height: 280px;
      background: linear-gradient(135deg, #1e293b, #334155);
      position: relative;
      overflow: hidden;
    }

    .team-card-img::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(59,130,246,0.15), rgba(245,158,11,0.1));
    }

    .team-card-img .initials {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      font-size: 3rem;
      font-weight: 700;
      color: rgba(255,255,255,0.12);
      z-index: 1;
    }

    .team-card-body { padding: 28px; }

    .team-card-quote {
      font-size: 0.95rem;
      color: var(--text-secondary);
      line-height: 1.65;
      margin-bottom: 24px;
      font-style: italic;
      position: relative;
      padding-left: 20px;
      border-left: 2px solid var(--accent);
    }

    .team-card-name {
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 4px;
    }

    .team-card-title {
      font-size: 0.85rem;
      color: var(--text-muted);
      margin-bottom: 2px;
    }

    .team-card-office {
      font-size: 0.8rem;
      color: var(--text-muted);
      margin-bottom: 20px;
    }

    .team-card-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--accent);
      transition: color 0.2s;
    }

    .team-card-cta:hover { color: var(--accent-hover); }
    .team-card-cta svg { width: 14px; height: 14px; }

    /* ===== WORK SHOWCASE ===== */
    .work-section {
      padding: var(--section-padding) 0;
      overflow: hidden;
    }

    .work-header {
      margin-bottom: 48px;
    }

    .work-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding-bottom: 30px;
      scrollbar-width: none;
      cursor: grab;
    }

    .work-carousel::-webkit-scrollbar { display: none; }

    .work-card {
      flex: 0 0 clamp(320px, 40vw, 500px);
      scroll-snap-align: start;
      border-radius: 16px;
      overflow: hidden;
      background: var(--bg-card);
      border: 1px solid var(--border);
      transition: border-color 0.3s, transform 0.3s;
    }

    .work-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
    }

    .work-card-img {
      width: 100%;
      height: 260px;
      background-size: cover;
      background-position: center;
      position: relative;
    }

    .work-card-body { padding: 28px; }

    .work-card-client {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 10px;
    }

    .work-card-title {
      font-size: 1.2rem;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 14px;
    }

    .work-card-quote {
      font-size: 0.88rem;
      color: var(--text-secondary);
      line-height: 1.6;
      font-style: italic;
      margin-bottom: 8px;
    }

    .work-card-author {
      font-size: 0.8rem;
      color: var(--text-muted);
    }

    .carousel-nav {
      display: flex;
      gap: 12px;
      margin-top: 24px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all 0.2s;
      color: var(--text-secondary);
    }

    .carousel-btn:hover {
      border-color: var(--text-primary);
      color: var(--text-primary);
    }

    .carousel-btn svg { width: 18px; height: 18px; }

    /* ===== CTA BANNER ===== */
    .cta-banner {
      padding: var(--section-padding) 0;
    }

    .cta-banner-inner {
      background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
      border-radius: 24px;
      padding: clamp(48px, 6vw, 80px) clamp(32px, 5vw, 72px);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .cta-banner-inner::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(59,130,246,0.12), transparent 70%);
      pointer-events: none;
    }

    .cta-banner-title {
      font-size: clamp(2rem, 4vw, 3.2rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 20px;
      position: relative;
    }

    .cta-banner-desc {
      font-size: clamp(1rem, 1.3vw, 1.15rem);
      color: var(--text-secondary);
      max-width: 640px;
      margin: 0 auto 36px;
      line-height: 1.6;
      position: relative;
    }

    .cta-banner-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 16px 36px;
      background: var(--text-primary);
      color: var(--bg);
      font-size: 1rem;
      font-weight: 600;
      border-radius: 100px;
      transition: transform 0.2s, box-shadow 0.2s;
      position: relative;
    }

    .cta-banner-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 10px 40px rgba(255,255,255,0.15);
    }

    /* ===== HOW WE WORK ===== */
    .how-section {
      padding: var(--section-padding) 0;
    }

    .how-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .how-visual {
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, #0f172a, #1e3a5f);
      border-radius: 20px;
      position: relative;
      overflow: hidden;
    }

    .how-visual::after {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 30% 40%, rgba(59,130,246,0.2), transparent 60%),
                  radial-gradient(circle at 80% 70%, rgba(245,158,11,0.12), transparent 50%);
    }

    .how-content .section-subtitle { margin-bottom: 36px; }

    .how-cta {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-size: 0.95rem;
      font-weight: 600;
      color: var(--accent);
      transition: color 0.2s;
    }

    .how-cta:hover { color: var(--accent-hover); }
    .how-cta svg { width: 16px; height: 16px; }

    @media (max-width: 768px) {
      .how-inner { grid-template-columns: 1fr; gap: 40px; }
    }

    /* ===== INSIGHTS ===== */
    .insights-section {
      padding: var(--section-padding) 0;
    }

    .insights-header { margin-bottom: 48px; }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 24px;
    }

    .insight-card {
      background: var(--bg-card);
      border-radius: 16px;
      overflow: hidden;
      border: 1px solid var(--border);
      transition: border-color 0.3s, transform 0.3s;
    }

    .insight-card:hover {
      border-color: var(--border-light);
      transform: translateY(-4px);
    }

    .insight-card-img {
      width: 100%;
      height: 200px;
      position: relative;
      overflow: hidden;
    }

    .insight-card-body { padding: 24px; }

    .insight-card-type {
      display: inline-block;
      font-size: 0.7rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 4px 12px;
      border-radius: 100px;
      margin-bottom: 14px;
    }

    .insight-card-type.podcast { background: rgba(139,92,246,0.15); color: #a78bfa; }
    .insight-card-type.article { background: rgba(59,130,246,0.15); color: var(--accent); }
    .insight-card-type.report { background: rgba(245,158,11,0.15); color: var(--accent-warm); }

    .insight-card-title {
      font-size: 1.05rem;
      font-weight: 700;
      line-height: 1.35;
      margin-bottom: 18px;
    }

    .insight-card-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--accent);
      transition: color 0.2s;
    }

    .insight-card-cta:hover { color: var(--accent-hover); }
    .insight-card-cta svg { width: 14px; height: 14px; }

    /* ===== PRINCIPLES ===== */
    .principles-section {
      padding: var(--section-padding) 0;
      border-top: 1px solid var(--border);
    }

    .principles-header { margin-bottom: 64px; }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 40px;
    }

    .principle-card { position: relative; }

    .principle-num {
      font-size: 4rem;
      font-weight: 900;
      color: rgba(255,255,255,0.04);
      line-height: 1;
      margin-bottom: 16px;
    }

    .principle-title {
      font-size: 1.2rem;
      font-weight: 700;
      margin-bottom: 14px;
      line-height: 1.3;
    }

    .principle-desc {
      font-size: 0.92rem;
      color: var(--text-secondary);
      line-height: 1.65;
    }

    /* ===== FOOTER ===== */
    .footer {
      border-top: 1px solid var(--border);
      padding: 80px 0 40px;
    }

    .footer-top {
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr;
      gap: 60px;
      margin-bottom: 60px;
